BEGIN;
INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'What are the general ''primary,'' ''secondary,'' and ''tertiary'' stages of effluent (wastewater) treatment at a textile ETP?', '["Primary removes larger solids/particles physically, secondary uses biological treatment to break down organic matter, and tertiary provides advanced polishing (e.g., color/chemical removal) before final discharge","All three stages are identical in function and exist purely as redundant backups for each other","Tertiary treatment happens BEFORE primary treatment in the correct process order","These terms refer only to different discharge pipe diameters, unrelated to any treatment process"]'::jsonb, 'Primary removes larger solids/particles physically, secondary uses biological treatment to break down organic matter, and tertiary provides advanced polishing (e.g., color/chemical removal) before final discharge', 'A typical ETP treatment train progresses from primary treatment (physical removal of larger solids/settleable material) through secondary treatment (biological processes breaking down dissolved organic pollutants) to tertiary treatment (advanced polishing steps like color removal, further filtration) before water meets discharge standards.', 2, '{"etp-treatment-stages"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What is ''GOTS'' (Global Organic Textile Standard) certification primarily concerned with?', '["Certifying textiles made from organically grown fiber that also meet defined environmental and social criteria throughout processing","Certifying only the exact color shade achieved in a dyed fabric","A certification that applies only to synthetic polyester fiber products","A certification concerned solely with fabric weight/GSM accuracy"]'::jsonb, 'Certifying textiles made from organically grown fiber that also meet defined environmental and social criteria throughout processing', 'GOTS certifies the full supply chain of textiles made from certified organically grown natural fiber, requiring compliance with environmental criteria (restricted chemicals, wastewater treatment) and social criteria (labor conditions) throughout processing — not just the raw fiber''s organic status alone.', 1, '{"gots-certification"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'Why might a buyer specifically require GOTS certification (rather than just any organic cotton claim) for an organic-labeled garment?', '["GOTS certification provides independently verified, traceable proof covering the full supply chain, environmental processing standards, and social criteria — not just an unverified raw-material claim","GOTS certification only checks the final garment''s color, unrelated to any organic fiber claim","An organic cotton claim without any certification is always equally trustworthy as a GOTS-certified claim","GOTS certification has no relationship to supply chain traceability whatsoever"]'::jsonb, 'GOTS certification provides independently verified, traceable proof covering the full supply chain, environmental processing standards, and social criteria — not just an unverified raw-material claim', 'An unverified organic claim relies solely on trust, while GOTS certification requires independent, traceable verification across the ENTIRE supply chain (not just the raw fiber) plus adherence to defined environmental and social processing standards — giving buyers much stronger assurance behind an ''organic'' claim than an uncertified statement alone.', 2, '{"gots-vs-uncertified-organic"}'::text[]);
COMMIT;
